seen = {}


@kt.kernel
def k(x=kt.In(8, 32), y=kt.Out(8, 32)):
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(2):
            r = c * 4 + t * 2
            seen["free"] = sorted(r.free())
            seen["affine"] = all(isinstance(a, E.Var) for a in r.terms)
            kt.store(y[r : r + 2, :], kt.load(x[r : r + 2, :]))


def facts():
    k.trace({"x": TY.TensorSpec.make((8, 32))}, machine=MACHINE)
    return seen
